/* CSA5111 Question 38: independent executable */
#include "common/crypto_common.h"
static void q38(void){char p[MAXBUF],c[MAXBUF];readstr("Known plaintext (letters, at least 4): ",p,sizeof p);readstr("Matching ciphertext (same length): ",c,sizeof c);char P[MAXBUF],C[MAXBUF];clean_alpha(p,P);clean_alpha(c,C);if(strlen(P)!=strlen(C)||strlen(P)<4){puts("Need equal strings of at least four letters.");return;}int found=0;for(int i=0;i<(int)strlen(P)-3;i++)for(int j=i+2;j<(int)strlen(P)-1;j++){int a=P[i]-'a',b=P[i+1]-'a',cc=P[j]-'a',d=P[j+1]-'a';int det=mod(a*d-b*cc,26),iv=inv_i(det,26);if(iv<0)continue;int x=C[i]-'a',y=C[i+1]-'a',z=C[j]-'a',w=C[j+1]-'a';int k00=mod((x*d-z*b)*iv,26),k01=mod((-x*cc+z*a)*iv,26),k10=mod((y*d-w*b)*iv,26),k11=mod((-y*cc+w*a)*iv,26);int ok=1;for(int t=0;t<(int)strlen(P);t+=2){if(t+1>=(int)strlen(P))break;int u=P[t]-'a',v=P[t+1]-'a';if(mod(k00*u+k01*v,26)!=C[t]-'a'||mod(k10*u+k11*v,26)!=C[t+1]-'a'){ok=0;break;}}if(ok){printf("Recovered Hill key: [%d %d; %d %d]\n",k00,k01,k10,k11);found=1;goto done;}}done:if(!found)puts("No invertible 2x2 plaintext pair recovered a consistent key; supply better known pairs.");}
int main(void){ OSSL_PROVIDER_load(NULL,"default"); OSSL_PROVIDER_load(NULL,"legacy"); q38(); return 0; }
